    },
    {
      "endpoint_type": "toxicity_change",
      "evidence_locator_ids": [
        "S03-E01",
        "S03-E02"
      ],
      "interpretation": "The FF\u2013EO treatment train decreased the toxic potency of the PFAS-contaminated waters, as measured by reduced TTR-binding activity (PFOS-equivalent) and reduced inhibition of A. fischeri bioluminescence (triclosan-equivalent), indicating a reduction in thyroid-disrupting and general toxicity potential.",
      "reported_term": "change in toxic potency assessed by transthyretin (TTR) binding and Aliivibrio fischeri bioluminescence assays"
    },
    {
      "endpoint_type": "degradation",
      "evidence_locator_ids": [
        "S03-E04"
      ],
      "interpretation": "Electrochemical degradation of PFSA in the fractionated foam was low, which may challenge the applicability of EO as a destructive technology for PFAS-enriched foam and suggests matrix-specific limitations or experimental artifacts.",
      "reported_term": "electrochemical degradation of PFSA in fractionated foam"
    }
  ],
  "limitations": [
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E04"
      ],
      "statement": "Low electrochemical degradation of PFSA in fractionated foam may challenge the applicability of EO as a destructive technology for PFAS-enriched foam; this may be due to artifacts or matrix-specific effects and needs confirmation by thorough mechanistic testing before full-scale implementation."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E06"
      ],
      "statement": "Formation of shorter-chain PFAS can occur when the total applied energy density during EO is insufficient, meaning PFAS may only be partially degraded rather than fully destroyed."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E06"
      ],
      "statement": "In waters containing chloride or bromide at relevant concentrations, EO can form perchlorate, bromate, and toxic organic halides, representing a substantial obstacle for industrial application and necessitating toxicity evaluation of EO-treated water."
